//! Each target's checked-in tables are what the pin's tblgen makes today.
//!
//! Every `crates/target/*/dagisel.toml` is regenerated by
//! `tools/dagisel/regen-target.sh` into a temporary directory and compared with
//! the record's `out`. `DAGISEL_SKIP_PIN=1` skips the test where
//! the pin's source and build are not installed.

use std::path::Path;
use std::process::Command;

#[test]
fn checked_in_target_tables_match_a_fresh_regeneration() {
    if std::env::var_os("DAGISEL_SKIP_PIN").is_some() {
        return;
    }
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../..");
    let mut records: Vec<_> = std::fs::read_dir(root.join("crates/target"))
        .unwrap()
        .map(|e| e.unwrap().path().join("dagisel.toml"))
        .filter(|p| p.exists())
        .collect();
    records.sort();
    for record in records {
        let doc: toml::Table = std::fs::read_to_string(&record).unwrap().parse().unwrap();
        let out = doc["target"]["out"].as_str().expect("[target] out");
        let checked_in = record.parent().unwrap().join(out);
        let fresh = tempfile::tempdir().unwrap();
        let status = Command::new(root.join("tools/dagisel/regen-target.sh"))
            .arg(&record)
            .arg(fresh.path())
            .env("DAGISEL_GEN", env!("CARGO_BIN_EXE_llrm-dagisel-gen"))
            .status()
            .expect("run regen-target.sh");
        assert!(status.success(), "regen-target.sh failed for {}; DAGISEL_SKIP_PIN=1 skips", record.display());
        let names = |dir: &Path| {
            let mut names: Vec<_> = std::fs::read_dir(dir).unwrap().map(|e| e.unwrap().file_name()).collect();
            names.sort();
            names
        };
        assert_eq!(names(&checked_in), names(fresh.path()), "the set of generated files changed");
        for name in names(&checked_in) {
            let old = std::fs::read_to_string(checked_in.join(&name)).unwrap();
            let new = std::fs::read_to_string(fresh.path().join(&name)).unwrap();
            assert!(old == new, "{} is stale: run tools/dagisel/regen-target.sh", checked_in.join(&name).display());
        }
    }
}
